from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def page(name,title,body):
 head=f'''<!doctype html><html lang="zh-CN" data-default-color="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f8f9fc"><meta name="description" content="一些日常，一些随手记录。"><title>{title}</title><link rel="icon" href="/assets/favicon.svg"><link rel="stylesheet" href="/fresh.css"><link rel="stylesheet" href="/{name}/style.css"><script src="/shared.js" defer></script><script src="/content.js" defer></script><script src="/reading.js" defer></script><script src="/behavior.js" defer></script><script src="/fresh-ui.js" defer></script></head><body>'''
 reader='''<dialog id="entry-reader" aria-labelledby="entry-title"><div class="reader-top"><span id="entry-kind"></span><button data-close-entry aria-label="关闭文章">×</button></div><h2 id="entry-title"></h2><div id="entry-copy"></div><div class="reader-bottom"><span>示例文字 · 慢慢读</span><button data-close-entry>读完了，返回 ↩</button></div></dialog>'''
 (ROOT/f'templates/{name}.html').write_text(head+body+reader+'</body></html>',encoding='utf-8')
 (ROOT/f'dist/{name}').mkdir(exist_ok=True)
